module TopModule (
    input  clk,
    input  load,
    input  [9:0] data,
    output reg tc
);

    reg [9:0] counter;

    always @(posedge clk) begin
        if (load) begin
            counter <= data;
            tc <= 1'b0;
        end else begin
            if (counter == 10'd0) begin
                tc <= 1'b1;
            end else begin
                counter <= counter - 1;
                tc <= 1'b0;
            end
        end
    end

endmodule

