    input  load,
    input  [255:0] data,
    output [255:0] q
);

    // Current state of the game
    reg [255:0] current_q;

    // Next state of the game
    reg [255:0] next_q;

    // Local variables for neighbor count
    reg [7:0] neighbor_count;

    // Function to compute the number of live neighbors for a given cell
    function [7:0] count_neighbors;
        input [7:0] row;
        input [7:0] col;
        begin
            count_neighbors = 0;
            for (int i = -1; i <= 1; i = i + 1) begin
                for (int j = -1; j <= 1; j = j + 1) begin
                    if (i == 0 && j == 0) continue;
                    int r = (row + i) % 16;
                    int c = (col + j) % 16;
                    if (current_q[(r * 16) + c]) count_neighbors = count_neighbors + 1;
                end
            end
        end
    endfunction

    // Compute next state
    always @(posedge clk) begin
        if (load) begin
            current_q <= data;
        end else begin
            next_q <= 256'd0;
            for (int i = 0; i < 16; i = i + 1) begin
                for (int j = 0; j < 16; j = j + 1) begin
                    neighbor_count = count_neighbors(i, j);
                    if (neighbor_count == 2) begin
                        next_q[(i * 16) + j] <= current_q[(i * 16) + j];
                    end else if (neighbor_count == 3) begin
                        next_q[(i * 16) + j] <= 1'b1;
                    end else begin
                        next_q[(i * 16) + j] <= 1'b0;
                    end
                end
            end
            current_q <= next_q;
        end
    end

    // Output the current state
    assign q = current_q;

endmodule

