                        fr1 <= 1'b0;
                        fr0 <= 1'b1;
                        dfr <= 1'b0;
                    end
                end else begin
                    // Between s[1] and s[0]
                    state <= 2'd1;
                    fr2 <= 1'b0;
                    fr1 <= 1'b1;
                    fr0 <= 1'b1;
                    dfr <= 1'b0;
                end
            end else begin
                // Below s[0]
                state <= 2'd0;
                fr2 <= 1'b1;
                fr1 <= 1'b1;
                fr0 <= 1'b1;
                dfr <= 1'b0;
            end

