module TopModule (
    input  clk,
    input  load,
    input  [255:0] data,
    output [255:0] q
);

    // Current state of the game
    reg [255:0] current_q;

    // Next state of the game
    reg [255:0] next_q;

    // Internal signals for neighbor count
    reg [255:0] neighbor_count;

    // Local parameters
    localparam ROWS = 16;
    localparam COLS = 16;
    localparam NEIGHBORS = 8;

    // Function to compute the number of neighbors for a cell
    function [7:0] count_neighbors;
        input [255:0] grid;
        input [3:0] row;
        input [3:0] col;
        begin
            count_neighbors = 0;
            for (int i = -1; i <= 1; i = i + 1) begin
                for (int j = -1; j <= 1; j = j + 1) begin
                    if (i == 0 && j == 0) continue;
                    int r = (row + i) % ROWS;
                    int c = (col + j) % COLS;
                    if (grid[(r * COLS) + c]) count_neighbors = count_neighbors + 1;
                end
            end
        end
    endfunction

    // Compute neighbor counts for all cells
    always @(current_q) begin
        neighbor_count = 0;
        for (int row = 0; row < ROWS; row = row + 1) begin
            for (int col = 0; col < COLS; col = col + 1) begin
                int index = (row * COLS) + col;
                neighbor_count[index] = count_neighbors(current_q, row, col);
            end
        end
    end

    // Compute next state based on neighbor counts
    always @(neighbor_count) begin
        next_q = 0;
        for (int row = 0; row < ROWS; row = row + 1) begin
            for (int col = 0; col < COLS; col = col + 1) begin
                int index = (row * COLS) + col;
                if (neighbor_count[index] == 2) begin
                    next_q[index] = current_q[index];
                end else if (neighbor_count[index] == 3) begin
                    next_q[index] = 1;
                end else begin
                    next_q[index] = 0;
                end
            end
        end
    end

    // Load data into current_q on the rising edge of load
    always @(posedge clk) begin
        if (load) begin
            current_q <= data;
        end else begin
            current_q <= next_q;
        end
    end

    // Output current state
    assign q = current_q;

endmodule

module TopModule (
    input  clk,
