module TopModule (
    input  clk,
    input  reset,
    input  [2:0] s,
    output reg fr2,
    output reg fr1,
    output reg fr0,
    output reg dfr
);

    // State machine states
    typedef enum reg [2:0] {
        STATE_LOW,      // Below s[0]
        STATE_MID_LOW,  // Between s[1] and s[0]
        STATE_MID_HIGH, // Between s[2] and s[1]
        STATE_HIGH      // Above s[2]
    } state_t;

    state_t current_state, next_state;
    reg [2:0] prev_s; // Previous sensor state

    // State transition logic
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            current_state <= STATE_LOW;
            prev_s <= 3'b111; // All sensors asserted (reset to low state)
        end else begin
            current_state <= next_state;
            prev_s <= s;
        end
    end

    // Next state logic
    always @(*) begin
        next_state = current_state;

        // Determine next state based on current and previous sensor states
        if (s == 3'b111) begin // Above s[2]
            next_state = STATE_HIGH;
        end else if (s == 3'b110) begin // Between s[2] and s[1]
            next_state = STATE_MID_HIGH;
        end else if (s == 3'b100) begin // Between s[1] and s[0]
            next_state = STATE_MID_LOW;
        end else if (s == 3'b000) begin // Below s[0]
            next_state = STATE_LOW;
        end
    end

    // Output logic based on current state and sensor change
    always @(*) begin
        fr2 = 1'b0;
        fr1 = 1'b0;
        fr0 = 1'b0;
        dfr = 1'b0;

        // Check if the previous level was lower than the current level
        reg sensor_changed = 0;
        reg prev_level_low = 0;
        reg current_level_low = 0;

        // Determine if the current level is low
        current_level_low = (s == 3'b000);

        // Determine if the previous level was low
        prev_level_low = (prev_s == 3'b000);

        // Check if the sensor level changed from low to not low
        sensor_changed = (prev_level_low && !current_level_low);

        // Set outputs based on current state
        case (current_state)
            STATE_LOW: begin
                fr2 = 1'b1;
                fr1 = 1'b1;
                fr0 = 1'b1;
                dfr = 1'b0;
            end
            STATE_MID_LOW: begin
                fr2 = 1'b1;
                fr1 = 1'b1;
                fr0 = 1'b1;
                dfr = 1'b0;
            end
            STATE_MID_HIGH: begin
                fr2 = 1'b0;
                fr1 = 1'b0;
                fr0 = 1'b1;
                dfr = 1'b0;
            end
            STATE_HIGH: begin
                fr2 = 1'b0;
                fr1 = 1'b0;
                fr0 = 1'b0;
                dfr = 1'b0;
            end
        endcase

        // If sensor changed from low to not low, open the supplemental flow valve
        if (sensor_changed) begin
            dfr = 1'b1;
        end
    end

endmodule

