            prev_sensors <= s;
            case (current_state)
                STATE_LOW: begin
                    if (s[0]) begin
                        next_state <= STATE_MID_LOW;
                        fr2 <= 1'b0;
                        fr1 <= 1'b0;
                        fr0 <= 1'b1;
                        dfr <= 1'b0;
                    end else begin
                        next_state <= STATE_LOW;
                        fr2 <= 1'b1;
                        fr1 <= 1'b1;
                        fr0 <= 1'b1;
                        dfr <= 1'b0;
                    end
                end

                STATE_MID_LOW: begin
                    if (s[1]) begin
                        next_state <= STATE_MID_HIGH;
                        fr2 <= 1'b0;
                        fr1 <= 1'b1;
                        fr0 <= 1'b1;
                        dfr <= 1'b0;
                    end else if (s[0]) begin
                        next_state <= STATE_MID_LOW;
                        fr2 <= 1'b0;
                        fr1 <= 1'b0;
                        fr0 <= 1'b1;
                        dfr <= 1'b0;
                    end else begin
                        next_state <= STATE_LOW;
                        fr2 <= 1'b1;
                        fr1 <= 1'b1;
                        fr0 <= 1'b1;
                        dfr <= 1'b0;
                    end
                end

                STATE_MID_HIGH: begin
                    if (s[2]) begin
                        next_state <= STATE_HIGH;
                        fr2 <= 1'b0;
                        fr1 <= 1'b0;
                        fr0 <= 1'b0;
                        dfr <= 1'b0;
                    end else if (s[1]) begin
                        next_state <= STATE_MID_HIGH;
                        fr2 <= 1'b0;
                        fr1 <= 1'b0;
                        fr0 <= 1'b1;
                        dfr <= 1'b0;
                    end else if (s[0]) begin
                        next_state <= STATE_MID_LOW;
                        fr2 <= 1'b0;
                        fr1 <= 1'b1;
                        fr0 <= 1'b1;
                        dfr <= 1'b0;
                    end else begin
                        next_state <= STATE_LOW;
                        fr2 <= 1'b1;
                        fr1 <= 1'b1;
                        fr0 <= 1'b1;
                        dfr <= 1'b0;
                    end
                end

                STATE_HIGH: begin
                    if (s[2]) begin
                        next_state <= STATE_HIGH;
                        fr2 <= 1'b0;
                        fr1 <= 1'b0;
                        fr0 <= 1'b0;
                        dfr <= 1'b0;
                    end else if (s[1]) begin
                        next_state <= STATE_MID_HIGH;
                        fr2 <= 1'b0;
                        fr1 <= 1'b0;
                        fr0 <= 1'b1;
                        dfr <= 1'b0;
                    end else if (s[0]) begin
                        next_state <= STATE_MID_LOW;
                        fr2 <= 1'b0;
                        fr1 <= 1'b1;
                        fr0 <= 1'b1;
                        dfr <= 1'b0;
                    end else begin
                        next_state <= STATE_LOW;
                        fr2 <= 1'b1;
                        fr1 <= 1'b1;
                        fr0 <= 1'b1;
                        dfr <= 1'b0;
                    end
                end

                default: begin
                    next_state <= STATE_LOW;
                    fr2 <= 1'b1;
                    fr1 <= 1'b1;
                    fr0 <= 1'b1;
                    dfr <= 1'b0;
                end
            endcase

            current_state <= next_state;
        end
    end

endmodule

module TopModule (
    input  clk,
    input  reset,
    input  [2:0] s,
    output reg fr2,
    output reg fr1,
    output reg fr0,
    output reg dfr
);

    // State definition: 0 = below s[0], 1 = between s[1] and s[0], 2 = between s[2] and s[1], 3 = above s[2]
    reg [1:0] state;

    // Previous sensor state
    reg [2:0] prev_s;

    // Determine the current water level state
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= 3; // Reset to state equivalent of being above s[2]
            prev_s <= 3'b111; // All sensors asserted (above s[2])
            fr2 <= 1'b1;
            fr1 <= 1'b1;
            fr0 <= 1'b1;
            dfr <= 1'b0;
        end else begin
            // Determine current state based on sensor inputs
            if (s[2]) begin
                if (s[1]) begin
                    if (s[0]) begin
                        state <= 3; // Above s[2]
                    end else begin
                        state <= 2; // Between s[2] and s[1]
                    end
                end else begin
                    state <= 1; // Between s[1] and s[0]
                end
            end else begin
                state <= 0; // Below s[0]
            end

            // Update previous sensor state
            prev_s <= s;
        end
    end

    // Determine flow rate based on current and previous sensor states
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            fr2 <= 1'b1;
            fr1 <= 1'b1;
            fr0 <= 1'b1;
            dfr <= 1'b0;
        end else begin
            case (state)
                3: begin // Above s[2]
                    fr2 <= 1'b0;
                    fr1 <= 1'b0;
                    fr0 <= 1'b0;
                    dfr <= 1'b0;
                end
                2: begin // Between s[2] and s[1]
                    fr2 <= 1'b0;
                    fr1 <= 1'b0;
                    fr0 <= 1'b1;
                    dfr <= 1'b0;
                end
                1: begin // Between s[1] and s[0]
                    fr2 <= 1'b0;
                    fr1 <= 1'b1;
                    fr0 <= 1'b1;
                    dfr <= (prev_s < s) ? 1'b1 : 1'b0;
                end
                0: begin // Below s[0]
                    fr2 <= 1'b1;
                    fr1 <= 1'b1;
                    fr0 <= 1'b1;
                    dfr <= 1'b0;
                end
            endcase
        end
    end

endmodule

module TopModule (
    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    input  ground,
    input  dig,
    output reg walk_left,
    output reg walk_right,
    output reg aaah,
    output reg digging
);

    // Define states
    typedef enum reg [2:0] {
        WALK_LEFT,
        WALK_RIGHT,
        FALLING,
        DIGGING
    } state_t;

    state_t current_state, next_state;
    reg prev_ground;
    reg prev_direction;
    reg was_falling;

    // State transition logic
    always @(posedge clk or posedge areset) begin
        if (areset) begin
            current_state <= WALK_LEFT;
            walk_left <= 1'b1;
            walk_right <= 1'b0;
            aaah <= 1'b0;
            digging <= 1'b0;
            prev_ground <= 1'b1;
            prev_direction <= 1'b1;
            was_falling <= 1'b0;
        end else begin
            prev_ground <= ground;
            was_falling <= (current_state == FALLING);

            // Determine next state based on current state and inputs
            case (current_state)
                WALK_LEFT: begin
                    // Check for bump
                    if (bump_right) begin
                        next_state = WALK_RIGHT;
                    end else if (bump_left) begin
                        next_state = WALK_RIGHT;
                    end else if (!ground) begin
                        next_state = FALLING;
                    end else if (dig) begin
                        next_state = DIGGING;
                    end else begin
                        next_state = WALK_LEFT;
                    end
                end

                WALK_RIGHT: begin
                    if (bump_left) begin
                        next_state = WALK_LEFT;
                    end else if (bump_right) begin
                        next_state = WALK_LEFT;
                    end else if (!ground) begin
                        next_state = FALLING;
                    end else if (dig) begin
                        next_state = DIGGING;
                    end else begin
                        next_state = WALK_RIGHT;
                    end
                end

                FALLING: begin
                    if (ground) begin
                        next_state = WALK_LEFT;
                    end else begin
                        next_state = FALLING;
                    end
                end

                DIGGING: begin
                    if (ground) begin
                        next_state = WALK_LEFT;
                    end else begin
                        next_state = FALLING;
                    end
                end

                default: next_state = WALK_LEFT;
            endcase

            current_state <= next_state;

            // Update outputs based on state
            case (current_state)
                WALK_LEFT: begin
                    walk_left <= 1'b1;
                    walk_right <= 1'b0;
                    aaah <= 1'b0;
                    digging <= 1'b0;
                end

                WALK_RIGHT: begin
                    walk_left <= 1'b0;
                    walk_right <= 1'b1;
                    aaah <= 1'b0;
                    digging <= 1'b0;
                end

                FALLING: begin
                    walk_left <= 1'b0;
                    walk_right <= 1'b0;
                    aaah <= 1'b1;
                    digging <= 1'b0;
                end

                DIGGING: begin
                    walk_left <= 1'b0;
                    walk_right <= 1'b0;
                    aaah <= 1'b0;
                    digging <= 1'b1;
                end

                default: begin
                    walk_left <= 1'b0;
                    walk_right <= 1'b0;
                    aaah <= 1'b0;
                    digging <= 1'b0;
                end
            endcase
        end
    end

endmodule

module TopModule (
    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    input  ground,
    input  dig,
    output reg walk_left,
    output reg walk_right,
    output reg aaah,
    output reg digging
);

    // Define states
    typedef enum reg [2:0] {
        WALK_LEFT,
        WALK_RIGHT,
        FALLING,
        DIGGING
    } state_t;

    state_t current_state, next_state;
    reg prev_ground;
    reg prev_direction;
    reg was_falling;

    // State transition logic
    always @(posedge clk or posedge areset) begin
        if (areset) begin
            current_state <= WALK_LEFT;
            walk_left <= 1'b1;
            walk_right <= 1'b0;
            aaah <= 1'b0;
            digging <= 1'b0;
            prev_ground <= 1'b1;
            prev_direction <= 1'b1;
            was_falling <= 1'b0;
        end else begin
            prev_ground <= ground;
            was_falling <= (current_state == FALLING);

            // Determine next state
            next_state = current_state;

            // Check for fall
            if (prev_ground == 1'b1 && ground == 1'b0) begin
                next_state = FALLING;
                aaah <= 1'b1;
                digging <= 1'b0;
            end else if (current_state == FALLING && ground == 1'b1) begin
                next_state = WALK_LEFT;
                walk_left <= prev_direction;
                walk_right <= 1'b0;
                aaah <= 1'b0;
            end else if (dig == 1'b1 && current_state == WALK_LEFT && ground == 1'b1) begin
                next_state = DIGGING;
                digging <= 1'b1;
                walk_left <= 1'b0;
                walk_right <= 1'b0;
            end else if (dig == 1'b1 && current_state == WALK_RIGHT && ground == 1'b1) begin
                next_state = DIGGING;
                digging <= 1'b1;
                walk_left <= 1'b0;
                walk_right <= 1'b0;
            end else if (current_state == DIGGING && ground == 1'b0) begin
                next_state = FALLING;
                aaah <= 1'b1;
                digging <= 1'b0;
            end else if (current_state == DIGGING && ground == 1'b1) begin
                next_state = WALK_LEFT;
                walk_left <= prev_direction;
                walk_right <= 1'b0;
                digging <= 1'b0;
            end else if (current_state == WALK_LEFT || current_state == WALK_RIGHT) begin
                if (bump_left && bump_right) begin
                    next_state = WALK_RIGHT;
                    walk_left <= 1'b0;
                    walk_right <= 1'b1;
                end else if (bump_left) begin
                    next_state = WALK_RIGHT;
                    walk_left <= 1'b0;
                    walk_right <= 1'b1;
                end else if (bump_right) begin
                    next_state = WALK_LEFT;
                    walk_left <= 1'b1;
                    walk_right <= 1'b0;
                end
            end

            // Update state and outputs
            current_state <= next_state;

            if (current_state == WALK_LEFT) begin
                walk_left <= 1'b1;
                walk_right <= 1'b0;
            end else if (current_state == WALK_RIGHT) begin
                walk_left <= 1'b0;
                walk_right <= 1'b1;
            end else if (current_state == FALLING) begin
                walk_left <= 1'b0;
                walk_right <= 1'b0;
            end else if (current_state == DIGGING) begin
                walk_left <= 1'b0;
                walk_right <= 1'b0;
            end
        end
    end

endmodule
